class Point{x=0;y=0;label="point";constructor(t,i){this.x=t,this.y=i}distanceFromOrigin(){return Math.sqrt(this.x*this.x+this.y*this.y)}toString(){return this.label+"("+this.x+","+this.y+")"}translate(t,i){return this.x+=t,this.y+=i,this}}const p1=new Point(3,4);print(p1.toString(),"dist="+p1.distanceFromOrigin()),p1.translate(1,1),print("after translate:",p1.toString());const p2=new Point;print("defaulted fields:",p2.toString());